///
/// Emit these rather than a string literal: the code is read from the
/// specification, so it cannot name a code the specification never
/// declared.
pub mod error_codes {
    /// `vtc/invitations/deliver:notFound`
    ///
    /// No invitation with that `id` exists.
    ///
    /// Declared `retryable: false`.
    pub const NOT_FOUND: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vtc/invitations/deliver:notFound",
        retryable: false,
    };
    /// `vtc/invitations/deliver:revoked`
    ///
    /// The invitation has been revoked, so there is nothing to deliver.
    ///
    /// Declared `retryable: false`.
    pub const REVOKED: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vtc/invitations/deliver:revoked",
        retryable: false,
    };
    /// `vtc/invitations/deliver:noRoute`
    ///
    /// On the `message` channel, the invited DID advertises no transport this community can send over. The `offer` channel still works.
    ///
    /// Declared `retryable: false`.
    pub const NO_ROUTE: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vtc/invitations/deliver:noRoute",
        retryable: false,
    };
}
#[cfg(test)]
mod conformance {
    //! Round-trip tests harvested from the spec's `spec.md`,
    //! plus a `rejects_invalid_examples` test for any fixtures
    //! in `payload.invalid-examples.json` (validate feature).
    #[test]
    fn request_example_1() {
        const JSON: &str = "{\n  \"id\": \"urn:uuid:00000000-0000-4000-8000-000000000001\",\n  \"type\": \"https://trusttasks.org/spec/vtc/invitations/deliver/0.1#request\",\n  \"issuer\": \"did:example:inviter\",\n  \"recipient\": \"did:webvh:QmCommunityScid:community.example\",\n  \"issuedAt\": \"2026-01-01T00:00:00Z\",\n  \"threadId\": \"urn:uuid:00000000-0000-4000-8000-0000000000ff\",\n  \"payload\": {\n    \"id\": \"urn:uuid:5f1c0b7e-9a4e-4c2a-8d11-3b0e6f7a2c90\",\n    \"channel\": \"offer\"\n  }\n}\n";
        let doc: crate::TrustTask<super::Payload> =
            serde_json::from_str(JSON).expect("deserialize request example");
        let rendered = serde_json::to_value(&doc).expect("re-serialize");
        let expected: serde_json::Value = serde_json::from_str(JSON).expect("re-parse expected");
        assert_eq!(rendered, expected, "request example failed round-trip");
    }
    #[test]
    fn response_example_1() {
        const JSON: &str = "{\n  \"id\": \"urn:uuid:00000000-0000-4000-8000-000000000002\",\n  \"type\": \"https://trusttasks.org/spec/vtc/invitations/deliver/0.1#response\",\n  \"issuer\": \"did:webvh:QmCommunityScid:community.example\",\n  \"recipient\": \"did:example:inviter\",\n  \"issuedAt\": \"2026-01-01T00:00:01Z\",\n  \"threadId\": \"urn:uuid:00000000-0000-4000-8000-0000000000ff\",\n  \"payload\": {\n    \"id\": \"urn:uuid:5f1c0b7e-9a4e-4c2a-8d11-3b0e6f7a2c90\",\n    \"channel\": \"offer\",\n    \"offer\": {\n      \"credential_issuer\": \"did:webvh:QmCommunityScid:community.example\",\n      \"credential_configuration_ids\": [\"VIC\"],\n      \"grants\": {\n        \"urn:ietf:params:oauth:grant-type:pre-authorized_code\": {\n          \"pre-authorized_code\": \"pac_3f9d2c1a7b6e4d5c8a0b1e2f3a4b5c6d\"\n        }\n      }\n    },\n    \"expiresAt\": \"2026-01-08T00:00:01Z\"\n  }\n}\n";
        let doc: crate::TrustTask<super::Response> =
            serde_json::from_str(JSON).expect("deserialize response example");
        let rendered = serde_json::to_value(&doc).expect("re-serialize");
        let expected: serde_json::Value = serde_json::from_str(JSON).expect("re-parse expected");
        assert_eq!(rendered, expected, "response example failed round-trip");
    }
    /// Each fixture in `payload.invalid-examples.json` MUST be
    /// rejected by at least one of: serde deserialization, or
    /// JSON-Schema validation under the `validate` feature. The
    /// fixture file documents the producer-side bug class that
    /// each payload exemplifies; this generated test pins it.
    #[cfg(feature = "validate")]
    #[test]
    fn rejects_invalid_examples() {
        use crate::validate::ValidatedPayload;
        let fixtures: &[(&str, &str)] = &[
            ("`id` is required.", "{\n  \"channel\": \"message\"\n}"),
            (
                "`channel` is required: delivering and handing over are different disclosures, so neither is a default.",
                "{\n  \"id\": \"urn:uuid:00000000-0000-4000-8000-000000000001\"\n}",
            ),
            (
                "`channel` is `message` or `offer`.",
                "{\n  \"channel\": \"email\",\n  \"id\": \"urn:uuid:00000000-0000-4000-8000-000000000001\"\n}",
            ),
            (
                "`id` must not be empty.",
                "{\n  \"channel\": \"offer\",\n  \"id\": \"\"\n}",
            ),
            (
                "Unknown top-level member is rejected: the invited DID is the invitation's, not the caller's to redirect.",
                "{\n  \"channel\": \"message\",\n  \"id\": \"urn:uuid:00000000-0000-4000-8000-000000000001\",\n  \"subjectDid\": \"did:example:someone-else\"\n}",
            ),
        ];
        for (i, (note, raw)) in fixtures.iter().enumerate() {
            let value: serde_json::Value = match serde_json::from_str(raw) {
                Ok(v) => v,
                Err(_) => continue,
            };
            let serde_ok = serde_json::from_value::<super::Payload>(value.clone()).is_ok();
            let schema_ok = super::Payload::validate_value(&value).is_ok();
            assert!(
                !(serde_ok && schema_ok),
                "invalid-example #{} ({:?}) was accepted by both serde and JSON Schema; \
                         the fixture's stated failure class is no longer caught:\n{}",
                i + 1,
                note,
                raw
            );
        }
    }
}
